# Echte Formularabläufe: Plan bleibt vor Bestätigung unverändert und U-Name bleibt im lokalen Entwurf.
import argparse,re
from browser_realtime import check_pages
from check_field_error_navigation_ui import shell
from check_work_report_layout import STATIC

def fixture():
    source=(STATIC/'work-report.js').read_text().split('// Die Klappschalter')[0]
    exported=r'''window.RosterFixture={setup(editor){user={id:7};key='roster-proposal-test';trainEditor=editor;state={client_id:'existing-report',saved_id:null,kind:'Sonstige Erfassung',ausbleibe:[],pause_policy:2,values:{}};pending=[];trips=[];plans={};monthCache={};reportViewOnly=false;el('dutyStart').value='2026-11-24T23:45';el('dutyEnd').value='2026-11-25T08:00';totals();storeDraft();},state:()=>state,pending:()=>pending,saved(){state.saved_id=42;state.train_dirty=false;reportViewOnly=true;}};})();'''
    source=re.sub(r'\}\)\(\);\s*$',lambda _:exported,source)
    setup=r'''
localStorage.clear();let gpsActive=false,writes=0;window.GpsRecorder={isActive:()=>gpsActive,mount:()=>null};window.I18n={t:s=>s,locale:'de-DE'};window.StationCatalog={search:async q=>[{code:q,name:q==='AAA'?'Alpha':'Beta'}]};
const roster={id:27,date:'2026-11-24',values:{duty_start:'2026-11-24T23:45:00',duty_end:'2026-11-25T08:00:00',activity:'Leerzug',from_station:'AAA',to_station:'BBB',departure:'25.11.2026 02:00',arrival:'25.11.2026 07:30',locomotives:'186 123',rotation:'Umlauf 4711',comment:'Übergabehinweis',provider:'Nicht anzeigen',preparation:'V1'}};
window.fetch=async(url,options={})=>{if(['POST','PUT','PATCH'].includes(options.method))writes++;return new Response(JSON.stringify(String(url).endsWith('/duty-rosters')?[roster]:{}));};
'''
    checks=r'''
(async()=>{const assert=(v,m)=>{if(!v)throw Error(m);},wait=()=>new Promise(r=>setTimeout(r,25)),until=async test=>{const end=Date.now()+10000;while(!test()){if(Date.now()>end)throw Error('Timeout');await wait();}},el=id=>document.getElementById(id);
el('workReport').hidden=false;el('reportDetails').hidden=false;
const editor=new TrainJourneyEditor({userId:7,container:el('trainJourneyEditor'),button:el('newTrainJourney'),readonly:()=>false,viewOnly:()=>false,bounds:()=>({start:el('dutyStart').value,end:el('dutyEnd').value}),minute:value=>Date.parse(value)/60000,clock:String,uuid:()=>crypto.randomUUID(),stations(){},resolve:async input=>({code:input.value.split(' · ')[0],name:'Bahnhof'}),changed(){},editingChanged(){},message(){},block(){}});
RosterFixture.setup(editor);editor.restore([{id:'old-train',train_number:'123',rotation_name:'Vorhandener Umlauf',start_station:'AAA',end_station:'BBB',start_at:'2026-11-24T23:50',end_at:'2026-11-25T00:15',events:[]}]);
await DutyRoster.open();const table=el('dutyRosterContent').querySelector('table'),headers=[...table.querySelectorAll('th')].map(n=>n.textContent);assert(headers.join('|')==='Dienstbeginn|Dienstende|Z-Art/P|S-Bhf|Z-Bhf|P-Abf(HH:MM)|P-Ank(HH:MM)|Tfz|Umlaufname|Hinweis','Exact compact column order');const cells=[...table.querySelectorAll('tr')[1].children].map(n=>n.textContent);assert(cells[0]==='24.11.26-23:45'&&cells[1]==='25.11.26-08:00'&&cells[5]==='02:00'&&cells[6]==='07:30','Local date/time formatting preserves midnight and does not shift timezone');assert(cells[8]==='Umlauf 4711'&&cells[9]==='Übergabehinweis','Rotation and note retained');
const before=JSON.stringify(editor.draft()),stored=localStorage.getItem('roster-proposal-test');table.querySelector('[data-duty-roster-entry]').click();await until(()=>el('dutyRosterProposal')?.open);assert(editor.items.length===1&&JSON.stringify(editor.draft())===before,'Selecting a row only opens the proposal');el('dutyRosterProposal').querySelector('button[type=button]').click();await until(()=>!el('dutyRosterProposal'));assert(JSON.stringify(editor.draft())===before&&localStorage.getItem('roster-proposal-test')===stored,'Cancel changes neither form nor local draft');await wait();
table.querySelector('[data-duty-roster-entry]').click();await until(()=>el('dutyRosterProposal')?.open);el('dutyRosterProposal').querySelector('[data-roster-accept]').click();await until(()=>editor.items.length===2&&!el('dutyRosterProposal'));assert(!el('dutyRosterDialog').open,'Both plan windows close after accepting');const item=editor.items[1];assert(editor.items[0].fields.rotation_name.value==='Vorhandener Umlauf','Previous journey is preserved');assert(item.fields.train_number.value===''&&item.fields.rotation_name.value==='Umlauf 4711','Rotation is proposed without inventing a train number');assert(item.fields.start_at.value==='2026-11-25T02:00'&&item.fields.end_at.value==='2026-11-25T07:30','Planned journey times preserve next-day date');assert(item.fields.start_station.value==='AAA · Alpha','Unique local station match is proposed');assert(!item.fields.rotation_name.required,'U-Name is optional');const numberBox=item.fields.train_number.getBoundingClientRect(),rotationBox=item.fields.rotation_name.getBoundingClientRect();assert(Math.abs(rotationBox.top-numberBox.top)<1&&rotationBox.left>=numberBox.right,'Rotation name is beside train number');const snapshot=JSON.parse(localStorage.getItem('roster-proposal-test'));assert(snapshot.train_journeys[1].rotation_name==='Umlauf 4711','Local draft retains rotation');assert(writes===0,'Accepting a proposal does not send a report');
await DutyRoster.open();el('dutyRosterContent').querySelector('[data-duty-roster-entry]').click();await until(()=>el('dutyRosterProposal')?.open);el('dutyRosterProposal').querySelector('[data-roster-accept]').click();await until(()=>el('dutyRosterProposal').querySelector('[role=alert]').textContent);assert(editor.items.length===2,'The same planned journey is not duplicated');el('dutyRosterProposal').querySelector('button[type=button]').click();await wait();el('dutyRosterDialog').close();
gpsActive=true;await DutyRoster.open();el('dutyRosterContent').querySelector('[data-duty-roster-entry]').click();await until(()=>el('dutyRosterContent').querySelector('[role=status]').textContent);assert(!el('dutyRosterProposal')&&editor.items.length===2,'An active GPS recording blocks applying planned data');el('dutyRosterDialog').close();gpsActive=false;
// Ein neuer Entwurf erhält den bisherigen vollständigen Entwurf, einschließlich U-Name.
item.fields.train_number.value='456';await DutyRoster.open();el('dutyRosterContent').querySelector('[data-duty-roster-entry]').click();await until(()=>el('dutyRosterProposal')?.open);el('dutyRosterProposal').querySelector('[data-roster-target]').value='new';el('dutyRosterProposal').querySelector('[data-roster-accept]').click();await until(()=>RosterFixture.state().client_id!=='existing-report'&&!el('dutyRosterProposal'));assert(RosterFixture.pending().some(r=>r.client_id==='existing-report'&&r.train_journeys.some(t=>t.rotation_name==='Umlauf 4711')),'Choosing a new draft keeps the old report locally');assert(editor.items.length===1&&editor.items[0].fields.rotation_name.value==='Umlauf 4711','New draft receives only the confirmed proposal');assert(writes===0,'No synchronization is triggered');
parent.postMessage({layoutStatus:'pass'},'*');})().catch(error=>parent.postMessage({layoutStatus:'fail',message:error.stack},'*'));
'''
    controllers='\n'.join((STATIC/name).read_text() for name in ['messages.js','work-report-feedback.js','report-tabs.js','train-journeys.js','duty-rosters.js'])
    return shell().replace('</body>','<script>'+setup+controllers+source+checks+'</script></body>')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--output-dir',required=True);a=p.parse_args();check_pages(fixture,a.output_dir,widths=(1280,800,375,320),label='Duty roster proposals',timeout=40)
